            ["\u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0640", "\u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637", "\u0645\u0631\u0627\u062C\u0639\u0629 \u0646\u0634\u0637\u0629", "AI Trading Desk"]
