        signalText: "\u039C\u03B9\u03B1 \u03B1\u03B4\u03CD\u03BD\u03B1\u03BC\u03B7 \u03C5\u03C0\u03B7\u03C1\u03B5\u03C3\u03AF\u03B1 \u03C3\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF \u03B5\u03BE\u03AC\u03C1\u03C4\u03B7\u03C3\u03B7. \u0388\u03BD\u03B1 \u03B9\u03C3\u03C7\u03C5\u03C1\u03CC trading system \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF \u03C3\u03B1\u03C6\u03AE\u03BD\u03B5\u03B9\u03B1: setup, \u03C1\u03AF\u03C3\u03BA\u03BF, \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03AF\u03C9\u03C3\u03B7, \u03B1\u03BA\u03CD\u03C1\u03C9\u03C3\u03B7 \u03BA\u03B1\u03B9 \u03C4\u03BF \u03BC\u03AC\u03B8\u03B7\u03BC\u03B1 \u03BC\u03B5\u03C4\u03AC \u03C4\u03BF \u03B1\u03C0\u03BF\u03C4\u03AD\u03BB\u03B5\u03C3\u03BC\u03B1.",
        signalCards: [
            ["\u0394\u03BF\u03BC\u03B7\u03BC\u03AD\u03BD\u03B1 \u03C3\u03AE\u03BC\u03B1\u03C4\u03B1", "\u03A4\u03B1 \u03C3\u03AE\u03BC\u03B1\u03C4\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03BF\u03BC\u03B7\u03BC\u03AD\u03BD\u03B5\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03BC\u03B5 \u03BA\u03B1\u03C4\u03B5\u03CD\u03B8\u03C5\u03BD\u03C3\u03B7, \u03AD\u03BD\u03B1\u03C5\u03C3\u03BC\u03B1, \u03B6\u03CE\u03BD\u03B7 \u03B5\u03B9\u03C3\u03CC\u03B4\u03BF\u03C5, stop, \u03C3\u03C4\u03CC\u03C7\u03BF\u03C5\u03C2 \u03BA\u03B1\u03B9 \u03C1\u03AF\u03C3\u03BA\u03BF."],
            ["\u0391\u03BD\u03AC\u03BB\u03C5\u03C3\u03B7 \u03C0\u03C1\u03B9\u03BD \u03B1\u03C0\u03CC \u03C4\u03B7\u03BD \u03B5\u03BD\u03AD\u03C1\u03B3\u03B5\u03B9\u03B1", "\u039A\u03AC\u03B8\u03B5 \u03C3\u03BF\u03B2\u03B1\u03C1\u03AE \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03B5\u03BE\u03B7\u03B3\u03B5\u03AF \u03B3\u03B9\u03B1\u03C4\u03AF \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5, \u03C4\u03B9 \u03C4\u03B7\u03BD \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03B9\u03CE\u03BD\u03B5\u03B9 \u03BA\u03B1\u03B9 \u03C4\u03B9 \u03C4\u03B7\u03BD \u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03AC \u03B5\u03C0\u03B9\u03BA\u03AF\u03BD\u03B4\u03C5\u03BD\u03B7."],
            ["Signal-to-Journal", "\u039C\u03B9\u03B1 \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03C0\u03BF\u03C5 \u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03B8\u03B7\u03BA\u03B5 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03BC\u03B5\u03C4\u03B1\u03C4\u03C1\u03B1\u03C0\u03B5\u03AF \u03C3\u03B5 \u03C3\u03C5\u03BD\u03B1\u03BB\u03BB\u03B1\u03B3\u03AE \u03C3\u03C4\u03BF \u03B7\u03BC\u03B5\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03BF, \u03CE\u03C3\u03C4\u03B5 \u03BD\u03B1 \u03C3\u03C5\u03B3\u03BA\u03C1\u03B9\u03B8\u03BF\u03CD\u03BD \u03C4\u03BF \u03C0\u03BB\u03AC\u03BD\u03BF \u03BA\u03B1\u03B9 \u03B7 \u03B5\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7."],
            ["\u039A\u03B1\u03B8\u03BF\u03B4\u03AE\u03B3\u03B7\u03C3\u03B7 \u03B1\u03C0\u03BF\u03C4\u03B5\u03BB\u03B5\u03C3\u03BC\u03AC\u03C4\u03C9\u03BD", "\u039F\u03B9 \u03B1\u03C0\u03BF\u03C6\u03AC\u03C3\u03B5\u03B9\u03C2 \u03C0\u03BF\u03C5 \u03C5\u03BB\u03BF\u03C0\u03BF\u03B9\u03AE\u03B8\u03B7\u03BA\u03B1\u03BD, \u03C0\u03B1\u03C1\u03B1\u03BB\u03B5\u03AF\u03C6\u03B8\u03B7\u03BA\u03B1\u03BD \u03AE \u03C7\u03AC\u03B8\u03B7\u03BA\u03B1\u03BD \u03B1\u03BD\u03B1\u03B4\u03B5\u03B9\u03BA\u03BD\u03CD\u03BF\u03C5\u03BD \u03C7\u03B1\u03BC\u03AD\u03BD\u03B5\u03C2 \u03B5\u03C5\u03BA\u03B1\u03B9\u03C1\u03AF\u03B5\u03C2, \u03C3\u03C9\u03C3\u03C4\u03AD\u03C2 \u03C0\u03B1\u03C1\u03B1\u03BB\u03B5\u03AF\u03C8\u03B5\u03B9\u03C2 \u03BA\u03B1\u03B9 \u03B1\u03B4\u03CD\u03BD\u03B1\u03BC\u03B7 \u03B5\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7."]
        ],
        comparisonTitle: "\u03A3\u03CD\u03B3\u03BA\u03C1\u03B9\u03C3\u03B7 \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03AC\u03C4\u03C9\u03BD",
