        finalTitle: "\u0397 \u03BE\u03B5\u03BA\u03AC\u03B8\u03B1\u03C1\u03B7 \u03C0\u03C1\u03CC\u03C4\u03B1\u03C3\u03B7",
        finalText: "\u0395\u03C0\u03AF\u03BB\u03B5\u03BE\u03B5 Core \u03B3\u03B9\u03B1 \u03B4\u03BF\u03BC\u03AE, Edge \u03B3\u03B9\u03B1 \u03B5\u03C5\u03C6\u03C5\u0390\u03B1 scanner \u03BA\u03B1\u03B9 \u03B5\u03BD\u03B5\u03C1\u03B3\u03AE \u03B1\u03BD\u03B1\u03C3\u03BA\u03CC\u03C0\u03B7\u03C3\u03B7, Elite \u03B3\u03B9\u03B1 real-time AI Alerts \u03BA\u03B1\u03B9 \u03C4\u03B7\u03BD \u03C0\u03BB\u03AE\u03C1\u03B7 \u03C1\u03BF\u03AE \u03B1\u03C0\u03CC \u03C4\u03BF \u03C3\u03AE\u03BC\u03B1 \u03C3\u03C4\u03BF \u03B7\u03BC\u03B5\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03BF.",
        disclaimer: "\u03A4\u03BF SkillEdge AI \u03B4\u03B5\u03BD \u03B1\u03C0\u03BF\u03C4\u03B5\u03BB\u03B5\u03AF \u03C7\u03C1\u03B7\u03BC\u03B1\u03C4\u03BF\u03BF\u03B9\u03BA\u03BF\u03BD\u03BF\u03BC\u03B9\u03BA\u03AE \u03C3\u03C5\u03BC\u03B2\u03BF\u03C5\u03BB\u03AE \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03B5\u03B3\u03B3\u03C5\u03AC\u03C4\u03B1\u03B9 \u03BA\u03AD\u03C1\u03B4\u03B7. \u0397 \u03C0\u03BB\u03B1\u03C4\u03C6\u03CC\u03C1\u03BC\u03B1 \u03AD\u03C7\u03B5\u03B9 \u03C3\u03C7\u03B5\u03B4\u03B9\u03B1\u03C3\u03C4\u03B5\u03AF \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B2\u03B5\u03BB\u03C4\u03B9\u03CE\u03BD\u03B5\u03B9 \u03C4\u03B7 \u03B4\u03BF\u03BC\u03AE, \u03C4\u03B7\u03BD \u03B1\u03BD\u03B1\u03C3\u03BA\u03CC\u03C0\u03B7\u03C3\u03B7, \u03C4\u03B7\u03BD \u03C0\u03BF\u03B9\u03CC\u03C4\u03B7\u03C4\u03B1 \u03C4\u03C9\u03BD \u03B1\u03C0\u03BF\u03C6\u03AC\u03C3\u03B5\u03C9\u03BD \u03BA\u03B1\u03B9 \u03C4\u03B7 \u03B4\u03B9\u03B1\u03B4\u03B9\u03BA\u03B1\u03C3\u03AF\u03B1 trading."
