            ["AI \u0914\u0930 \u0921\u0947\u091F\u093E \u0932\u0947\u092F\u0930", "\u0938\u094D\u0915\u0948\u0928\u0930 \u0932\u0949\u091C\u093F\u0915, AI \u092A\u094D\u0930\u0949\u092E\u094D\u092A\u094D\u091F\u094D\u0938, \u0921\u0947\u091F\u093E \u0938\u0902\u0935\u0930\u094D\u0927\u0928, \u0909\u092A\u092F\u094B\u0917 \u0938\u0940\u092E\u093E\u090F\u0901 \u0914\u0930 \u092C\u0948\u0915\u090F\u0902\u0921 \u0917\u0947\u091F\u094D\u0938 \u0924\u0948\u092F\u093E\u0930 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964"],
            ["\u0921\u093F\u091C\u093C\u093E\u0907\u0928 \u0914\u0930 \u0905\u0928\u0941\u092D\u0935", "\u0921\u0948\u0936\u092C\u094B\u0930\u094D\u0921, \u0938\u093E\u0930\u094D\u0935\u091C\u0928\u093F\u0915 \u092A\u0947\u091C, \u0932\u0949\u0915\u094D\u0921 \u0938\u094D\u091F\u0947\u091F\u094D\u0938, \u0932\u094B\u0921\u093F\u0902\u0917 \u0938\u094D\u091F\u0947\u091F\u094D\u0938 \u0914\u0930 \u092A\u094D\u0930\u0940\u092E\u093F\u092F\u092E \u0907\u0902\u091F\u0930\u092B\u093C\u0947\u0938 \u0915\u094B \u0906\u0915\u093E\u0930 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964"],
            ["\u0938\u092A\u094B\u0930\u094D\u091F \u0911\u092A\u0930\u0947\u0936\u0902\u0938", "\u0917\u094D\u0930\u093E\u0939\u0915 \u092A\u094D\u0930\u0936\u094D\u0928\u094B\u0902, \u0911\u092A\u0930\u0947\u091F\u0930 \u092B\u093C\u094D\u0932\u094B, \u092D\u0941\u0917\u0924\u093E\u0928\u094B\u0902, \u090F\u0915\u094D\u0938\u0947\u0938 \u0914\u0930 \u092A\u094D\u0930\u094B\u0921\u0915\u094D\u091F \u092E\u093E\u0930\u094D\u0917\u0926\u0930\u094D\u0936\u0928 \u0915\u094B \u0938\u0902\u092D\u093E\u0932\u0924\u0947 \u0939\u0948\u0902\u0964"],
            ["\u0938\u093F\u0915\u094D\u092F\u094B\u0930\u093F\u091F\u0940 \u0914\u0930 \u0907\u0902\u092B\u094D\u0930\u093E\u0938\u094D\u091F\u094D\u0930\u0915\u094D\u091A\u0930", "\u0928\u093F\u091C\u0940 \u090F\u0915\u094D\u0938\u0947\u0938, \u092A\u094D\u0932\u0947\u091F\u092B\u093C\u0949\u0930\u094D\u092E \u0921\u0947\u091F\u093E, \u0930\u0947\u091F \u0932\u093F\u092E\u093F\u091F\u094D\u0938 \u0914\u0930 \u0915\u094D\u0932\u093E\u0907\u0902\u091F \u0935\u0930\u094D\u0915\u092B\u093C\u094D\u0932\u094B\u091C\u093C \u0915\u0940 \u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964"]
