        roadmapEyebrow: "\u0930\u094B\u0921\u092E\u0948\u092A",
        roadmapTitle: "\u0939\u092E \u090F\u0915 \u092A\u094D\u0930\u0940\u092E\u093F\u092F\u092E AI Trading Desk \u0915\u0940 \u0926\u093F\u0936\u093E \u092E\u0947\u0902 \u0928\u093F\u0930\u094D\u092E\u093E\u0923 \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902\u0964",
